    LA: 'lo', MM: 'my', KH: 'km',
    // Slavic / Balkan
    BG: 'bg', HR: 'hr', RS: 'sr', SK: 'sk', SI: 'sl',
    // Ukrainian
    UA: 'uk',
    // Turkish
    TR: 'tr',
    // Thai
    TH: 'th',
    // Arabic
    SA: 'ar', AE: 'ar', EG: 'ar', QA: 'ar', KW: 'ar', OM: 'ar', BH: 'ar',
    DZ: 'ar', MA: 'ar', TN: 'ar', IQ: 'ar', JO: 'ar', LB: 'ar',
    // Korean
    KR: 'ko',
    // Traditional Chinese
    TW: 'zh', HK: 'zh',
    // Simplified Chinese
    CN: 'zh-CN', SG: 'zh-CN',
    // Japanese
    JP: 'ja',
    // Hebrew
    IL: 'he',
    // Swedish
    SE: 'sv',
    // Czech
    CZ: 'cs',
    // Danish
    DK: 'da',
    // Finnish
    FI: 'fi',
    // Hungarian
    HU: 'hu',
    // Somali
    SO: 'so',
    // Swahili
    KE: 'sw', TZ: 'sw',
    // Amharic
    ET: 'am',
