  // Detect appropriate locale from URL query (?lang= or ?hl=), stored preference, or browser language.
  function detectLocale(navLang, countryHint) {
    if (typeof window !== 'undefined' && window.location && window.location.search) {
      try {
        const params = new URLSearchParams(window.location.search);
        let queryLang = (params.get('lang') || params.get('hl') || '').trim().toLowerCase();
        if (queryLang === PSEUDO_LOCALE) return PSEUDO_LOCALE;
        if (queryLang) {
          if (queryLang.startsWith('zh-cn') || queryLang.startsWith('zh-sg') || queryLang === 'zh-hans') {
            queryLang = 'zh-cn';
          } else if (queryLang.startsWith('zh')) {
            queryLang = 'zh';
          }
          let matched = null;
          for (let i = 0; i < LOCALES.length; i++) {
            if (LOCALES[i].code.toLowerCase() === queryLang) {
              matched = LOCALES[i].code;
              break;
            }
          }
          if (!matched) {
            const prefix = queryLang.split(/[-_]/)[0];
            for (let i = 0; i < LOCALES.length; i++) {
              if (LOCALES[i].code.toLowerCase() === prefix) {
                matched = LOCALES[i].code;
                break;
              }
            }
          }
          if (matched) {
            try { if (typeof localStorage !== 'undefined') localStorage.setItem('att_locale', matched); } catch {}
            return matched;
          }
        }
      } catch {}
    }

    if (typeof localStorage !== 'undefined') {
      try {
        const stored = localStorage.getItem('att_locale');
        if (stored && STRINGS[stored]) return stored;
      } catch { /* ignored */ }
    }
    const raw = String(
      navLang ||
      (typeof navigator !== 'undefined' ? (navigator.language || (navigator.languages && navigator.languages[0])) : 'en') ||
      'en'
    ).toLowerCase();

    if (raw.startsWith('zh-cn') || raw.startsWith('zh-sg') || raw === 'zh-hans') return 'zh-CN';
    if (raw.startsWith('zh')) return 'zh';
    if (raw.startsWith('ta')) return 'ta';
    if (raw.startsWith('te')) return 'te';
    if (raw.startsWith('bn')) return 'bn';
    if (raw.startsWith('ur')) return 'ur';
    if (raw.startsWith('he') || raw.startsWith('iw')) return 'he';
    if (raw.startsWith('mr')) return 'mr';
    if (raw.startsWith('sv')) return 'sv';
    if (raw.startsWith('ru')) return 'ru';
    if (raw.startsWith('uk')) return 'uk';
    if (raw.startsWith('ro')) return 'ro';
    if (raw.startsWith('es')) return 'es';
    if (raw.startsWith('pt')) return 'pt';
    if (raw.startsWith('hi')) return 'hi';
    if (raw.startsWith('tl') || raw.startsWith('fil')) return 'tl';
    if (raw.startsWith('id') || raw.startsWith('in')) return 'id';
    if (raw.startsWith('ms')) return 'ms';
    if (raw.startsWith('vi')) return 'vi';
    if (raw.startsWith('fr')) return 'fr';
    if (raw.startsWith('de')) return 'de';
    if (raw.startsWith('it')) return 'it';
    if (raw.startsWith('nl')) return 'nl';
    if (raw.startsWith('pl')) return 'pl';
    if (raw.startsWith('tr')) return 'tr';
    if (raw.startsWith('th')) return 'th';
    if (raw.startsWith('ar')) return 'ar';
    if (raw.startsWith('ko')) return 'ko';
    if (raw.startsWith('ja')) return 'ja';
    if (raw.startsWith('cs')) return 'cs';
    if (raw.startsWith('da')) return 'da';
    if (raw.startsWith('fi')) return 'fi';
    if (raw.startsWith('hu')) return 'hu';
    if (raw.startsWith('so')) return 'so';
    if (raw.startsWith('sw')) return 'sw';
    if (raw.startsWith('am')) return 'am';
    if (raw.startsWith('si')) return 'si';
    if (raw.startsWith('el')) return 'el';
    if (raw.startsWith('no') || raw.startsWith('nb') || raw.startsWith('nn')) return 'no';
    if (raw.startsWith('ca')) return 'ca';
    if (raw.startsWith('ne')) return 'ne';
    if (raw.startsWith('ml')) return 'ml';
    if (raw.startsWith('mn')) return 'mn';
    if (raw.startsWith('kn')) return 'kn';
    if (raw.startsWith('gu')) return 'gu';
    if (raw.startsWith('pa')) return 'pa';
    if (raw.startsWith('kk')) return 'kk';
    if (raw.startsWith('lv')) return 'lv';
    if (raw.startsWith('lt')) return 'lt';
    if (raw.startsWith('lo')) return 'lo';
    if (raw.startsWith('my')) return 'my';
    if (raw.startsWith('km')) return 'km';
    if (raw.startsWith('ceb')) return 'ceb';
    if (raw.startsWith('bg')) return 'bg';
    if (raw.startsWith('hr')) return 'hr';
    if (raw.startsWith('sr')) return 'sr';
    if (raw.startsWith('sk')) return 'sk';
    if (raw.startsWith('sl')) return 'sl';
    if (raw.startsWith('af')) return 'af';

    // Country-based fallback: if raw is English or unrecognized, inspect country hint or region tag
    const parts = raw.split(/[-_]/);
    const countryFromHint = typeof countryHint === 'string' ? countryHint.trim().toUpperCase() : '';
    const countryFromNav = parts.length > 1 ? parts[1].trim().toUpperCase() : '';
    const countryFromWindow = (typeof window !== 'undefined' && (window._attCountry || window._signupCountry || ''))
      ? String(window._attCountry || window._signupCountry).trim().toUpperCase()
      : '';

    const candidateCountry = (countryFromHint && COUNTRY_TO_LOCALE[countryFromHint])
      ? countryFromHint
      : (countryFromNav && COUNTRY_TO_LOCALE[countryFromNav])
      ? countryFromNav
      : countryFromWindow;

    if (candidateCountry && COUNTRY_TO_LOCALE[candidateCountry]) {
      return COUNTRY_TO_LOCALE[candidateCountry];
    }

    return 'en';
  }

  function setLocale(l, persist) {
    // The pseudo-locale renders English (wrapped); never persisted.
    pseudo = l === PSEUDO_LOCALE;
    if (pseudo) {
      l = 'en';
      persist = false;
    }
    if (STRINGS[l]) {
      locale = l;
      if (typeof document !== 'undefined' && document.documentElement) {
        document.documentElement.lang = l;
        document.documentElement.dir = (l === 'ar' || l === 'he' || l === 'ur') ? 'rtl' : 'ltr';
      }
      if (persist) {
        if (typeof localStorage !== 'undefined') {
          try { localStorage.setItem('att_locale', l); } catch { /* quota/private mode */ }
        }
        if (typeof document !== 'undefined') {
          try {
            document.cookie = 'att_locale=' + encodeURIComponent(l) + ';path=/;max-age=31536000;SameSite=Lax';
          } catch {}
        }
      }
    }
    return locale;
  }

  // Automatically translate any elements in the DOM with data-i18n attributes.
  function applyTranslations(rootEl) {
    const doc = rootEl || (typeof document !== 'undefined' ? document : null);
    if (!doc || !doc.querySelectorAll) return;

    doc.querySelectorAll('[data-i18n]').forEach(el => {
      const key = el.getAttribute('data-i18n');
      if (key) {
        const val = t(key, el.textContent);
        if (typeof val === 'string' && val.indexOf('<') !== -1 && val.indexOf('>') !== -1) {
          el.innerHTML = val;
        } else {
          el.textContent = val;
        }
      }
    });

    doc.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
      const key = el.getAttribute('data-i18n-placeholder');
      if (key) el.setAttribute('placeholder', t(key, el.getAttribute('placeholder')));
    });

    doc.querySelectorAll('[data-i18n-title]').forEach(el => {
      const key = el.getAttribute('data-i18n-title');
      if (key) el.setAttribute('title', t(key, el.getAttribute('title')));
    });

    doc.querySelectorAll('[data-i18n-aria]').forEach(el => {
      const key = el.getAttribute('data-i18n-aria');
      if (key) el.setAttribute('aria-label', t(key, el.getAttribute('aria-label')));
    });

    doc.querySelectorAll('[data-i18n-alt]').forEach(el => {
      const key = el.getAttribute('data-i18n-alt');
      if (key) el.setAttribute('alt', t(key, el.getAttribute('alt')));
    });
  }

  // Render a responsive 60-language switcher into any target container
  function renderLanguagePicker(container) {
    const el = typeof container === 'string' ? document.getElementById(container) : container;
    if (!el) return;

    const current = locale;
    const select = document.createElement('select');
    select.className = 'att-lang-picker';
    select.setAttribute('aria-label', 'Select Language');
    select.style.cssText = 'background:#161b22;color:#e6edf3;border:1px solid #30363d;border-radius:6px;padding:5px 10px;font-size:0.82rem;cursor:pointer;font-family:inherit;outline:none;';

    LOCALES.forEach(loc => {
      const opt = document.createElement('option');
      opt.value = loc.code;
      opt.textContent = `${loc.flag} ${loc.label}`;
      if (loc.code === current) opt.selected = true;
      select.appendChild(opt);
    });

    select.addEventListener('change', e => {
      const chosen = e.target.value;
      setLocale(chosen, true);
      applyTranslations();
      if (typeof window !== 'undefined' && typeof window.updateUiLanguage === 'function') {
        window.updateUiLanguage();
      }
      // Update URL query param without reload if history API available
      if (typeof window !== 'undefined' && window.location) {
        const url = new URL(window.location.href);
        url.searchParams.set('lang', chosen);
        if (window.history && window.history.replaceState) {
          window.history.replaceState({}, '', url.toString());
        } else {
          window.location.href = url.toString();
        }
      }
    });

    el.innerHTML = '';
    el.appendChild(select);
  }

